16	import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
17	import { MessageHashUtils } from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
18	import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
19	import { Initializable } from "@solady/src/utils/Initializable.sol";
20	import { SafeTransferLib } from "@solady/src/utils/SafeTransferLib.sol";
21	
22	import { Constants } from "../utils/Constants.sol";
23	import { Errors } from "../utils/Errors.sol";
24	
25	import { ILegionAddressRegistry } from "../interfaces/registries/ILegionAddressRegistry.sol";
26	import { ILegionCapitalRaise } from "../interfaces/raise/ILegionCapitalRaise.sol";
27	
28	import { LegionPositionManager } from "../position/LegionPositionManager.sol";
29	
30	/**
31	 * @title Legion Capital Raise
32	 * @author Legion
33	 * @notice Manages capital raising for ERC20 token sales before Token Generation Event (TGE).
34	 * @dev Handles the complete pre-liquid capital raise lifecycle including investments, refunds, withdrawals, and
35	 * position management using soulbound NFTs.
36	 */
37	contract LegionCapitalRaise is ILegionCapitalRaise, LegionPositionManager, Initializable, Pausable {
38	    using ECDSA for bytes32;
39	    using MessageHashUtils for bytes32;
40	
41	    /// @dev Struct containing the pre-liquid capital raise configuration.
42	    CapitalRaiseConfig private s_capitalRaiseConfig;
43	
44	    /// @dev Struct tracking the current capital raise status.
45	    CapitalRaiseStatus private s_capitalRaiseStatus;
46	
47	    /// @dev Mapping of position IDs to their positions.
48	    mapping(uint256 s_positionId => InvestorPosition s_investorPosition) private s_investorPositions;
49	
50	    /// @dev Mapping to track used signatures per investor.
51	    mapping(address s_investorAddress => mapping(bytes s_signature => bool s_used) s_usedSignature) private
52	        s_usedSignatures;
53	
54	    /// @notice Restricts function access to the Legion bouncer only.
55	    /// @dev Reverts if the caller is not the configured Legion bouncer address.
56	    modifier onlyLegion() {
57	        if (msg.sender != s_capitalRaiseConfig.legionBouncer) revert Errors.LegionSale__NotCalledByLegion();
58	        _;
59	    }
60	
61	    /// @notice Restricts function access to the project admin only.
62	    /// @dev Reverts if the caller is not the configured project admin address.
63	    modifier onlyProject() {
64	        if (msg.sender != s_capitalRaiseConfig.projectAdmin) revert Errors.LegionSale__NotCalledByProject();
65	        _;
66	    }
67	
68	    /// @notice Restricts function access to either Legion bouncer or project admin.
69	    /// @dev Reverts if the caller is neither the project admin nor Legion bouncer.
70	    modifier onlyLegionOrProject() {
71	        if (msg.sender != s_capitalRaiseConfig.projectAdmin && msg.sender != s_capitalRaiseConfig.legionBouncer) {
72	            revert Errors.LegionSale__NotCalledByLegionOrProject();
73	        }
74	        _;
75	    }
76	
77	    /// @notice Restricts function execution when the capital raise is canceled.
78	    /// @dev Reverts if the capital raise has not been canceled.
79	    modifier whenRaiseCanceled() {
80	        // Verify that the capital raise has been canceled
81	        _verifyCapitalRaiseIsCanceled();
82	        _;
83	    }
84	
85	    /// @notice Restricts function execution when the capital raise is not canceled.
86	    /// @dev Reverts if the capital raise has been canceled.
87	    modifier whenRaiseNotCanceled() {
88	        // Verify that the capital raise has not been canceled
89	        _verifyCapitalRaisedNotCanceled();
90	        _;
91	    }
92	
93	    /// @notice Restricts function execution when the capital raise has ended.
94	    /// @dev Reverts if the capital raise has not ended.
95	    modifier whenRaiseHasEnded() {
96	        // Verify that the capital raise has ended
97	        _verifyCapitalRaiseHasEnded();
98	        _;
99	    }
100	
101	    /// @notice Restricts function execution when the capital raise has not ended.
102	    /// @dev Reverts if the capital raise has ended.
103	    modifier whenRaiseNotEnded() {
104	        // Verify that the capital raise has not ended
105	        _verifyCapitalRaiseHasNotEnded();
106	        _;
107	    }
108	
109	    /// @notice Restricts interaction to when the refund period is over.
110	    /// @dev Reverts if the refund period is not over.
111	    modifier whenRefundPeriodIsOver() {
112	        // Verify that the refund period is over
113	        _verifyRefundPeriodIsOver();
114	        _;
115	    }
116	
117	    /// @notice Restricts interaction to when the refund period is not over.
118	    /// @dev Reverts if the refund period is over.
119	    modifier whenRefundPeriodNotOver() {
120	        // Verify that the refund period is not over
121	        _verifyRefundPeriodIsNotOver();
122	        _;
123	    }
124	
125	    /// @notice Constructor for the LegionCapitalRaise contract.
126	    /// @dev Prevents the implementation contract from being initialized directly.
127	    constructor() {
128	        // Disable initialization
129	        _disableInitializers();
130	    }
131	
132	    /// @inheritdoc ILegionCapitalRaise
133	    function initialize(CapitalRaiseInitializationParams calldata capitalRaiseInitParams) external initializer {
134	        _setLegionCapitalRaiseConfig(capitalRaiseInitParams);
135	    }
136	
137	    /// @inheritdoc ILegionCapitalRaise
138	    function invest(
139	        uint256 amount,
140	        uint256 investAmount,
141	        uint256 tokenAllocationRate,
142	        bytes calldata investSignature
143	    )
144	        external
145	        whenNotPaused
146	        whenRaiseNotCanceled
147	        whenRaiseNotEnded
148	    {
149	        // Check if the investor has already invested
150	        // If not, create a new investor position
151	        uint256 positionId = _getInvestorPositionId(msg.sender) == 0
152	            ? _createInvestorPosition(msg.sender)
153	            : s_investorPositionIds[msg.sender];
154	
155	        // Verify that the investor has not refunded
156	        _verifyHasNotRefunded(positionId);
157	
158	        // Verify that the invest signature has not been used
159	        _verifySignatureNotUsed(investSignature);
160	
161	        // Verify that the investor has not claimed excess capital
162	        _verifyCanClaimExcessCapital(positionId);
163	
164	        // Load the investor position
165	        InvestorPosition storage position = s_investorPositions[positionId];
166	
167	        // Increment total capital invested from investors
168	        s_capitalRaiseStatus.totalCapitalInvested += amount;
169	
170	        // Increment total capital for the investor
171	        position.investedCapital += amount;
172	
173	        // Mark the signature as used
174	        s_usedSignatures[msg.sender][investSignature] = true;
175	
176	        // Update the investor position
177	        _updateInvestorPosition(investAmount, tokenAllocationRate);
178	
179	        // Verify that the investor position is valid
180	        _verifyValidPosition(investSignature, positionId, CapitalRaiseAction.INVEST);
181	
182	        // Emit CapitalInvested
183	        emit CapitalInvested(amount, msg.sender, positionId);
184	
185	        // Transfer the invested capital to the contract
186	        SafeTransferLib.safeTransferFrom(s_capitalRaiseConfig.bidToken, msg.sender, address(this), amount);
187	    }
188	
189	    /// @inheritdoc ILegionCapitalRaise
190	    function refund() external whenNotPaused whenRaiseNotCanceled whenRefundPeriodNotOver {
191	        // Get the investor position ID
192	        uint256 positionId = _getInvestorPositionId(msg.sender);
193	
194	        // Verify that the position exists
195	        _verifyPositionExists(positionId);
196	
197	        // Verify that the investor has not refunded
198	        _verifyHasNotRefunded(positionId);
199	
200	        // Load the investor position
201	        InvestorPosition storage position = s_investorPositions[positionId];
202	
203	        // Cache the amount to refund in memory
204	        uint256 amountToRefund = position.investedCapital;
205	
206	        // Set the total invested capital for the investor to 0
207	        position.investedCapital = 0;
208	
209	        // Flag that the investor has refunded
210	        s_investorPositions[positionId].hasRefunded = true;
211	
212	        // Decrement total capital invested from all investors
213	        s_capitalRaiseStatus.totalCapitalInvested -= amountToRefund;
214	
215	        // Emit CapitalRefunded
216	        emit CapitalRefunded(amountToRefund, msg.sender, positionId);
217	
218	        // Transfer the refunded amount back to the investor
219	        SafeTransferLib.safeTransfer(s_capitalRaiseConfig.bidToken, msg.sender, amountToRefund);
220	    }
221	
222	    /// @inheritdoc ILegionCapitalRaise
223	    function emergencyWithdraw(address receiver, address token, uint256 amount) external onlyLegion {
224	        // Emit EmergencyWithdraw
225	        emit EmergencyWithdraw(receiver, token, amount);
226	
227	        // Transfer the amount to Legion's address
228	        SafeTransferLib.safeTransfer(token, receiver, amount);
229	    }
230	
231	    /// @inheritdoc ILegionCapitalRaise
232	    function withdrawRaisedCapital()
233	        external
234	        onlyProject
235	        whenNotPaused
236	        whenRaiseNotCanceled
237	        whenRaiseHasEnded
238	        whenRefundPeriodIsOver
239	    {
240	        // Verify that the project can withdraw capital
241	        _verifyCanWithdrawCapital();
242	
243	        // Cache value in memory
244	        uint256 _totalCapitalRaised = s_capitalRaiseStatus.totalCapitalRaised;
245	
246	        // Account for the capital withdrawn
247	        s_capitalRaiseStatus.totalCapitalWithdrawn = _totalCapitalRaised;
248	
249	        // Cache the sale configuration
250	        CapitalRaiseConfig memory capitalRaiseConfig = s_capitalRaiseConfig;
251	
252	        // Calculate Legion Fee
253	        uint256 legionFee =
254	            (capitalRaiseConfig.legionFeeOnCapitalRaisedBps * _totalCapitalRaised) / Constants.BASIS_POINTS_DENOMINATOR;
255	
256	        // Calculate Referrer Fee
257	        uint256 referrerFee = (capitalRaiseConfig.referrerFeeOnCapitalRaisedBps * _totalCapitalRaised)
258	            / Constants.BASIS_POINTS_DENOMINATOR;
259	
260	        // Emit CapitalWithdrawn
261	        emit CapitalWithdrawn(_totalCapitalRaised);
262	
263	        // Transfer the amount to the Project's address
264	        SafeTransferLib.safeTransfer(
265	            capitalRaiseConfig.bidToken, msg.sender, (_totalCapitalRaised - legionFee - referrerFee)
266	        );
267	
268	        // Transfer the Legion fee to the Legion fee receiver address
269	        if (legionFee != 0) {
270	            SafeTransferLib.safeTransfer(capitalRaiseConfig.bidToken, capitalRaiseConfig.legionFeeReceiver, legionFee);
271	        }
272	
273	        // Transfer the Referrer fee to the Referrer fee receiver address
274	        if (referrerFee != 0) {
275	            SafeTransferLib.safeTransfer(
276	                capitalRaiseConfig.bidToken, capitalRaiseConfig.referrerFeeReceiver, referrerFee
277	            );
278	        }
279	    }
280	
281	    /// @inheritdoc ILegionCapitalRaise
282	    function cancel() external onlyProject whenNotPaused whenRaiseNotCanceled {
283	        // Cache the amount of funds to be returned to the capital raise
284	        // The project should return the total capital raised including the charged fees
285	        uint256 capitalToReturn = s_capitalRaiseStatus.totalCapitalWithdrawn;
286	
287	        // Mark the capital raise as canceled
288	        s_capitalRaiseStatus.isCanceled = true;
289	
290	        // Emit CapitalRaiseCanceled
291	        emit CapitalRaiseCanceled();
292	
293	        // In case there's capital to return, transfer the funds back to the contract
294	        if (capitalToReturn > 0) {
295	            // Set the totalCapitalWithdrawn to zero
296	            s_capitalRaiseStatus.totalCapitalWithdrawn = 0;
297	            // Transfer the raised capital back to the contract
298	            SafeTransferLib.safeTransferFrom(s_capitalRaiseConfig.bidToken, msg.sender, address(this), capitalToReturn);
299	        }
300	    }
301	
302	    /// @inheritdoc ILegionCapitalRaise
303	    function withdrawInvestedCapitalIfCanceled() external whenNotPaused whenRaiseCanceled {
304	        // Get the investor position ID
305	        uint256 positionId = _getInvestorPositionId(msg.sender);
306	
307	        // Verify that the position exists
308	        _verifyPositionExists(positionId);
309	
310	        // Cache the amount to refund in memory
311	        uint256 amountToClaim = s_investorPositions[positionId].investedCapital;
312	
313	        // Revert in case there's nothing to claim
314	        if (amountToClaim == 0) revert Errors.LegionSale__InvalidWithdrawAmount(0);
315	
316	        // Set the total invested capital for the investor to 0
317	        s_investorPositions[positionId].investedCapital = 0;
318	
319	        // Decrement total capital invested from all investors
320	        s_capitalRaiseStatus.totalCapitalInvested -= amountToClaim;
321	
322	        // Emit CapitalRefundedAfterCancel
323	        emit CapitalRefundedAfterCancel(amountToClaim, msg.sender, positionId);
324	
325	        // Transfer the refunded amount back to the investor
326	        SafeTransferLib.safeTransfer(s_capitalRaiseConfig.bidToken, msg.sender, amountToClaim);
327	    }
328	
329	    /// @inheritdoc ILegionCapitalRaise
330	    function withdrawExcessInvestedCapital(
331	        uint256 amount,
332	        uint256 investAmount,
333	        uint256 tokenAllocationRate,
334	        bytes calldata claimExcessSignature
335	    )
336	        external
337	        whenNotPaused
338	        whenRaiseNotCanceled
339	    {
340	        // Get the investor position ID
341	        uint256 positionId = _getInvestorPositionId(msg.sender);
342	
343	        // Verify that the position exists
344	        _verifyPositionExists(positionId);
345	
346	        // Verify that the signature has not been used
347	        _verifySignatureNotUsed(claimExcessSignature);
348	
349	        // Verify that the investor is eligible to get excess capital back
350	        _verifyCanClaimExcessCapital(positionId);
351	
352	        // Load the investor position
353	        InvestorPosition storage position = s_investorPositions[positionId];
354	
355	        // Decrement total capital invested from investors
356	        s_capitalRaiseStatus.totalCapitalInvested -= amount;
357	
358	        // Decrement total investor capital for the investor
359	        position.investedCapital -= amount;
360	
361	        // Mark that the excess capital has been returned
362	        position.hasClaimedExcess = true;
363	
364	        // Mark the signature as used
365	        s_usedSignatures[msg.sender][claimExcessSignature] = true;
366	
367	        // Update the investor position
368	        _updateInvestorPosition(investAmount, tokenAllocationRate);
369	
370	        // Verify that the investor position is valid
371	        _verifyValidPosition(claimExcessSignature, positionId, CapitalRaiseAction.WITHDRAW_EXCESS_CAPITAL);
372	
373	        // Emit ExcessCapitalWithdrawn
374	        emit ExcessCapitalWithdrawn(amount, msg.sender, positionId);
375	
376	        // Transfer the excess capital to the investor
377	        if (amount > 0) SafeTransferLib.safeTransfer(s_capitalRaiseConfig.bidToken, msg.sender, amount);
378	    }
379	
380	    /// @inheritdoc ILegionCapitalRaise
381	    function end() external onlyLegionOrProject whenNotPaused whenRaiseNotEnded whenRaiseNotCanceled {
382	        // Update the `hasEnded` status to true
383	        s_capitalRaiseStatus.hasEnded = true;
384	
385	        // Set the `endTime` of the capital raise
386	        s_capitalRaiseStatus.endTime = uint64(block.timestamp);
387	
388	        // Set the `refundEndTime` of the capital raise
389	        s_capitalRaiseStatus.refundEndTime = uint64(block.timestamp) + s_capitalRaiseConfig.refundPeriodSeconds;
390	
391	        // Emit CapitalRaiseEnded
392	        emit CapitalRaiseEnded();
393	    }
394	
395	    /// @inheritdoc ILegionCapitalRaise
396	    function publishRaisedCapital(uint256 capitalRaised)
397	        external
398	        onlyLegion
399	        whenNotPaused
400	        whenRaiseNotCanceled
401	        whenRaiseHasEnded
402	        whenRefundPeriodIsOver
403	    {
404	        // Verify that capital raised can be published.
405	        _verifyCanPublishCapitalRaised();
406	
407	        // Set the total capital raised to be withdrawn by the project
408	        s_capitalRaiseStatus.totalCapitalRaised = capitalRaised;
409	
410	        // Emit CapitalRaisedPublished
411	        emit CapitalRaisedPublished(capitalRaised);
412	    }
413	
414	    /// @inheritdoc LegionPositionManager
415	    function transferInvestorPosition(
416	        address from,
417	        address to,
418	        uint256 positionId
419	    )
420	        external
421	        override
422	        onlyLegion
423	        whenNotPaused
424	        whenRaiseNotCanceled
425	        whenRaiseHasEnded
426	        whenRefundPeriodIsOver
427	    {
428	        // Verify that the position can be transferred
429	        _verifyCanTransferInvestorPosition(positionId);
430	
431	        // Burn or transfer the investor position
432	        _burnOrTransferInvestorPosition(from, to, positionId);
433	    }
434	
435	    /// @inheritdoc LegionPositionManager
436	    function transferInvestorPositionWithAuthorization(
437	        address from,
438	        address to,
439	        uint256 positionId,
440	        bytes calldata signature
441	    )
442	        external
443	        virtual
444	        override
445	        whenNotPaused
446	        whenRaiseNotCanceled
447	        whenRaiseHasEnded
448	        whenRefundPeriodIsOver
449	    {
450	        // Verify the signature for transferring the position
451	        _verifyTransferSignature(from, to, positionId, s_capitalRaiseConfig.legionSigner, signature);
452	
453	        // Verify that the position can be transferred
454	        _verifyCanTransferInvestorPosition(positionId);
455	
456	        // Burn or transfer the investor position
457	        _burnOrTransferInvestorPosition(from, to, positionId);
458	    }
459	
460	    /// @inheritdoc ILegionCapitalRaise
461	    function syncLegionAddresses() external onlyLegion {
462	        _syncLegionAddresses();
463	    }
464	
465	    /// @inheritdoc ILegionCapitalRaise
466	    function pause() external virtual onlyLegion {
467	        // Pause the capital raise
468	        _pause();
469	    }
470	
471	    /// @inheritdoc ILegionCapitalRaise
472	    function unpause() external virtual onlyLegion {
473	        // Unpause the capital raise
474	        _unpause();
475	    }
476	
477	    /// @inheritdoc ILegionCapitalRaise
478	    function saleConfiguration() external view returns (CapitalRaiseConfig memory) {
479	        return s_capitalRaiseConfig;
480	    }
481	
482	    /// @inheritdoc ILegionCapitalRaise
483	    function saleStatus() external view returns (CapitalRaiseStatus memory) {
484	        return s_capitalRaiseStatus;
485	    }
486	
487	    /// @inheritdoc ILegionCapitalRaise
488	    function investorPosition(address investor) external view returns (InvestorPosition memory) {
489	        // Get the investor position ID
490	        uint256 positionId = _getInvestorPositionId(investor);
491	
492	        // Verify that the position exists
493	        _verifyPositionExists(positionId);
494	
495	        return s_investorPositions[positionId];
496	    }
497	
498	    /// @dev Sets the capital raise parameters during initialization.
499	    /// @param _preLiquidSaleInitParams The initialization parameters.
500	    function _setLegionCapitalRaiseConfig(CapitalRaiseInitializationParams calldata _preLiquidSaleInitParams)
501	        private
502	        onlyInitializing
503	    {
504	        // Verify if the capital raise configuration is valid
505	        _verifyValidConfig(_preLiquidSaleInitParams);
506	
507	        // Initialize the capital raise configuration
508	        s_capitalRaiseConfig.refundPeriodSeconds = _preLiquidSaleInitParams.refundPeriodSeconds;
509	        s_capitalRaiseConfig.legionFeeOnCapitalRaisedBps = _preLiquidSaleInitParams.legionFeeOnCapitalRaisedBps;
510	        s_capitalRaiseConfig.referrerFeeOnCapitalRaisedBps = _preLiquidSaleInitParams.referrerFeeOnCapitalRaisedBps;
511	        s_capitalRaiseConfig.bidToken = _preLiquidSaleInitParams.bidToken;
512	        s_capitalRaiseConfig.projectAdmin = _preLiquidSaleInitParams.projectAdmin;
513	        s_capitalRaiseConfig.addressRegistry = _preLiquidSaleInitParams.addressRegistry;
514	        s_capitalRaiseConfig.referrerFeeReceiver = _preLiquidSaleInitParams.referrerFeeReceiver;
515	
516	        // Initialize pre-liquid sale soulbound token configuration
517	        s_positionManagerConfig.name = _preLiquidSaleInitParams.saleName;
518	        s_positionManagerConfig.symbol = _preLiquidSaleInitParams.saleSymbol;
519	        s_positionManagerConfig.baseURI = _preLiquidSaleInitParams.saleBaseURI;
520	
521	        // Cache Legion addresses from `LegionAddressRegistry`
522	        _syncLegionAddresses();
523	    }
524	
525	    /// @dev Synchronizes Legion addresses from the registry.
526	    function _syncLegionAddresses() private {
527	        // Cache Legion addresses from `LegionAddressRegistry`
528	        s_capitalRaiseConfig.legionBouncer =
529	            ILegionAddressRegistry(s_capitalRaiseConfig.addressRegistry).getLegionAddress(Constants.LEGION_BOUNCER_ID);
530	        s_capitalRaiseConfig.legionSigner =
531	            ILegionAddressRegistry(s_capitalRaiseConfig.addressRegistry).getLegionAddress(Constants.LEGION_SIGNER_ID);
532	        s_capitalRaiseConfig.legionFeeReceiver = ILegionAddressRegistry(s_capitalRaiseConfig.addressRegistry)
533	            .getLegionAddress(Constants.LEGION_FEE_RECEIVER_ID);
534	
535	        // Emit LegionAddressesSynced
536	        emit LegionAddressesSynced(
537	            s_capitalRaiseConfig.legionBouncer,
538	            s_capitalRaiseConfig.legionSigner,
539	            s_capitalRaiseConfig.legionFeeReceiver
540	        );
541	    }
542	
543	    /// @dev Updates an investor's position with new investment and allocation data.
544	    /// @param _investAmount The maximum capital allowed to invest.
545	    /// @param _tokenAllocationRate The token allocation percentage (18 decimals precision).
546	    function _updateInvestorPosition(uint256 _investAmount, uint256 _tokenAllocationRate) private {
547	        // Get the investor position ID
548	        uint256 positionId = _getInvestorPositionId(msg.sender);
549	
550	        // Verify that the position exists
551	        _verifyPositionExists(positionId);
552	
553	        // Load the investor position
554	        InvestorPosition storage position = s_investorPositions[positionId];
555	
556	        // Cache the SAFT amount the investor is allowed to invest
557	        if (position.cachedInvestAmount != _investAmount) {
558	            position.cachedInvestAmount = _investAmount;
559	        }
560	
561	        // Cache the token allocation rate in 18 decimals precision
562	        if (position.cachedTokenAllocationRate != _tokenAllocationRate) {
563	            position.cachedTokenAllocationRate = _tokenAllocationRate;
564	        }
565	    }
566	
567	    /// @dev Burns or transfers an investor position based on receiver's existing position.
568	    /// @param _from The address of the current owner.
569	    /// @param _to The address of the new owner.
570	    /// @param _positionId The ID of the position to transfer or burn.
571	    function _burnOrTransferInvestorPosition(address _from, address _to, uint256 _positionId) private {
572	        // Get the position ID of the receiver
573	        uint256 positionIdTo = s_investorPositionIds[_to];
574	
575	        // If the receiver already has a position, burn the transferred position
576	        // and update the existing position
577	        if (positionIdTo != 0) {
578	            // Load the investor positions
579	            InvestorPosition memory positionToBurn = s_investorPositions[_positionId];
580	            InvestorPosition storage positionToUpdate = s_investorPositions[positionIdTo];
581	
582	            // Verify that the updated position is not settled or refunded
583	            if (positionToUpdate.hasRefunded || !positionToUpdate.hasClaimedExcess) {
584	                revert Errors.LegionSale__UnableToMergeInvestorPosition(positionIdTo);
585	            }
586	
587	            // Update the existing position with the transferred values
588	            positionToUpdate.investedCapital += positionToBurn.investedCapital;
589	            positionToUpdate.cachedTokenAllocationRate += positionToBurn.cachedTokenAllocationRate;
590	            positionToUpdate.cachedInvestAmount += positionToBurn.cachedInvestAmount;
591	
592	            // Delete the burned position
593	            delete s_investorPositions[_positionId];
594	
595	            // Burn the investor position from the `from` address
596	            _burnInvestorPosition(_from);
597	        } else {
598	            // Transfer the investor position to the new address
599	            _transferInvestorPosition(_from, _to, _positionId);
600	        }
601	    }
602	
603	    /// @dev Validates the capital raise configuration parameters.
604	    /// @param _preLiquidSaleInitParams The initialization parameters to validate.
605	    function _verifyValidConfig(CapitalRaiseInitializationParams calldata _preLiquidSaleInitParams) private pure {
606	        // Check for zero addresses provided
607	        if (
608	            _preLiquidSaleInitParams.bidToken == address(0) || _preLiquidSaleInitParams.projectAdmin == address(0)
609	                || _preLiquidSaleInitParams.addressRegistry == address(0)
610	        ) revert Errors.LegionSale__ZeroAddressProvided();
611	
612	        // Check for zero values provided
613	        if (_preLiquidSaleInitParams.refundPeriodSeconds == 0) {
614	            revert Errors.LegionSale__ZeroValueProvided();
615	        }
616	
617	        // Check if the refund period is within range
618	        if (_preLiquidSaleInitParams.refundPeriodSeconds > 2 weeks) revert Errors.LegionSale__InvalidPeriodConfig();
619	    }
620	
621	    /// @dev Ensures the capital raise is not canceled.
622	    function _verifyCapitalRaisedNotCanceled() internal view {
623	        if (s_capitalRaiseStatus.isCanceled) revert Errors.LegionSale__SaleIsCanceled();
624	    }
625	
626	    /// @dev Ensures the capital raise is canceled.
627	    function _verifyCapitalRaiseIsCanceled() internal view {
628	        if (!s_capitalRaiseStatus.isCanceled) revert Errors.LegionSale__SaleIsNotCanceled();
629	    }
630	
631	    /// @dev Ensures the capital raise has not ended.
632	    function _verifyCapitalRaiseHasNotEnded() internal view {
633	        if (s_capitalRaiseStatus.hasEnded) revert Errors.LegionSale__SaleHasEnded(block.timestamp);
634	    }
635	
636	    /// @dev Ensures the capital raise has ended.
637	    function _verifyCapitalRaiseHasEnded() internal view {
638	        if (!s_capitalRaiseStatus.hasEnded) revert Errors.LegionSale__SaleHasNotEnded(block.timestamp);
639	    }
640	
641	    /// @dev Ensures a signature has not been used before.
642	    /// @param _signature The signature to verify.
643	    function _verifySignatureNotUsed(bytes calldata _signature) private view {
644	        // Check if the signature is used
645	        if (s_usedSignatures[msg.sender][_signature]) revert Errors.LegionSale__SignatureAlreadyUsed(_signature);
646	    }
647	
648	    /// @dev Verifies conditions for withdrawing capital.
649	    function _verifyCanWithdrawCapital() internal view virtual {
650	        // Load the sale status
651	        CapitalRaiseStatus memory capitalRaiseStatus = s_capitalRaiseStatus;
652	        // Check if capital has not been withdrawn
653	        if (capitalRaiseStatus.totalCapitalWithdrawn > 0) revert Errors.LegionSale__CapitalAlreadyWithdrawn();
654	        // Check if capital raised has been published
655	        if (capitalRaiseStatus.totalCapitalRaised == 0) revert Errors.LegionSale__CapitalNotRaised();
656	    }
657	
658	    /// @dev Ensures the refund period has ended.
659	    function _verifyRefundPeriodIsOver() internal view {
660	        // Cache the refund end time from the sale configuration
661	        uint256 refundEndTime = s_capitalRaiseStatus.refundEndTime;
662	        if (refundEndTime > 0 && block.timestamp < refundEndTime) {
663	            revert Errors.LegionSale__RefundPeriodIsNotOver(block.timestamp, refundEndTime);
664	        }
665	    }
666	
667	    /// @dev Ensures the refund period is still active.
668	    function _verifyRefundPeriodIsNotOver() internal view {
669	        // Cache the refund end time from the sale configuration
670	        uint256 refundEndTime = s_capitalRaiseStatus.refundEndTime;
671	        if (refundEndTime > 0 && block.timestamp >= refundEndTime) {
672	            revert Errors.LegionSale__RefundPeriodIsOver(block.timestamp, refundEndTime);
673	        }
674	    }
675	
676	    /// @dev Ensures the investor has not already refunded.
677	    /// @param _positionId The ID of the investor's position.
678	
679	    function _verifyHasNotRefunded(uint256 _positionId) internal view virtual {
680	        if (s_investorPositions[_positionId].hasRefunded) revert Errors.LegionSale__InvestorHasRefunded(msg.sender);
681	    }
682	
683	    /// @dev Verifies conditions for publishing capital raised.
684	    function _verifyCanPublishCapitalRaised() internal view {
685	        if (s_capitalRaiseStatus.totalCapitalRaised != 0) revert Errors.LegionSale__CapitalRaisedAlreadyPublished();
686	    }
687	
688	    /// @dev Validates an investor's position using signature verification.
689	    /// @param _signature The signature to verify.
690	    /// @param _positionId The ID of the investor's position.
691	    /// @param _actionType The type of capital raise action being performed.
692	    function _verifyValidPosition(
693	        bytes calldata _signature,
694	        uint256 _positionId,
695	        CapitalRaiseAction _actionType
696	    )
697	        internal
698	        view
699	    {
700	        // Load the investor position
701	        InvestorPosition memory position = s_investorPositions[_positionId];
702	
703	        // Verify that the amount invested is equal to the SAFT amount
704	        if (position.investedCapital != position.cachedInvestAmount) {
705	            revert Errors.LegionSale__InvalidPositionAmount(msg.sender);
706	        }
707	
708	        // Construct the signed data
709	        bytes32 _data = keccak256(
710	            abi.encodePacked(
711	                msg.sender,
712	                address(this),
713	                block.chainid,
714	                uint256(position.cachedInvestAmount),
715	                uint256(position.cachedTokenAllocationRate),
716	                _actionType
717	            )
718	        ).toEthSignedMessageHash();
719	
720	        // Verify the signature
721	        if (_data.recover(_signature) != s_capitalRaiseConfig.legionSigner) {
722	            revert Errors.LegionSale__InvalidSignature(_signature);
723	        }
724	    }
725	
726	    /// @dev Verifies investor eligibility to claim excess capital.
727	    /// @param _positionId The position ID of the investor.
728	    function _verifyCanClaimExcessCapital(uint256 _positionId) internal view virtual {
729	        // Load the investor position
730	        InvestorPosition memory position = s_investorPositions[_positionId];
731	
732	        // Check if the investor has already claimed excess capital
733	        if (position.hasClaimedExcess) revert Errors.LegionSale__AlreadyClaimedExcess(msg.sender);
734	    }
735	
736	    /// @dev Verifies conditions for transferring an investor position.
737	    /// @param _positionId The ID of the investor's position.
738	    function _verifyCanTransferInvestorPosition(uint256 _positionId) private view {
739	        // Load the investor position
740	        InvestorPosition memory position = s_investorPositions[_positionId];
741	
742	        // Verify that the position is not refunded
743	        if (position.hasRefunded || !position.hasClaimedExcess) {
744	            revert Errors.LegionSale__UnableToTransferInvestorPosition(_positionId);
745	        }
746	    }
747	}
748	

